def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full-length color-2 barrier.
    horizontal = next(
        (r for r, row in enumerate(grid) if all(v == 2 for v in row)),
        None
    )
    vertical = None
    if horizontal is None:
        vertical = next(
            (c for c in range(w) if all(grid[r][c] == 2 for r in range(h))),
            None
        )
    if horizontal is None and vertical is None:
        return [row[:] for row in grid]

    # The most common non-barrier color is the background.
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != 2]
    out = [[bg] * w for _ in range(h)]

    if horizontal is not None:
        side_below = any(r > horizontal for r, c, v in points)
        if side_below:
            delta = horizontal + 1 - min(r for r, c, v in points)
            moved = [(r + delta, c, v) for r, c, v in points]
            trail = max(r for r, c, v in moved) + 1
            if 0 <= trail < h:
                out[trail] = [8] * w
        else:
            delta = horizontal - 1 - max(r for r, c, v in points)
            moved = [(r + delta, c, v) for r, c, v in points]
            trail = min(r for r, c, v in moved) - 1
            if 0 <= trail < h:
                for r in range(h):
                    out[r] = [8] * w if r == trail else out[r]
        for r, row in enumerate(grid):
            if r == horizontal:
                out[r] = row[:]
        for r, c, v in moved:
            if 0 <= r < h:
                out[r][c] = v

    else:
        side_right = any(c > vertical for r, c, v in points)
        if side_right:
            delta = vertical + 1 - min(c for r, c, v in points)
            moved = [(r, c + delta, v) for r, c, v in points]
            trail = max(c for r, c, v in moved) + 1
        else:
            delta = vertical - 1 - max(c for r, c, v in points)
            moved = [(r, c + delta, v) for r, c, v in points]
            trail = min(c for r, c, v in moved) - 1

        for r in range(h):
            out[r][vertical] = 2
        if 0 <= trail < w:
            for r in range(h):
                out[r][trail] = 8
        for r, c, v in moved:
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = v

    return out
